import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Button,
  CircularProgress,
  Alert,
  Chip,
  Card,
  Grid,
  Avatar,
} from "@mui/material";
import { CheckCircle, Cancel, PersonAdd } from "@mui/icons-material";
import API from "../../api/axios";
import { colors } from "../../theme";

const StaffApprovals = () => {
  const [pendingStaff, setPendingStaff] = useState([]);
  const [loading, setLoading] = useState(true);
  const [alert, setAlert] = useState({
    show: false,
    message: "",
    severity: "success",
  });

  useEffect(() => {
    fetchPending();
  }, []);

  const fetchPending = async () => {
    try {
      const response = await API.get("/admin/pending-staff");
      setPendingStaff(response.data);
    } catch (error) {
      console.error("Failed to fetch pending staff:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleApprove = async (id) => {
    try {
      await API.put(`/admin/approve-staff/${id}`, { status: "active" });
      showAlert("Staff account approved!");
      fetchPending();
    } catch (error) {
      showAlert("Failed to approve staff.", "error");
    }
  };

  const handleReject = async (id) => {
    try {
      await API.put(`/admin/approve-staff/${id}`, { status: "rejected" });
      showAlert("Staff account rejected successfully.", "success");
      fetchPending();
    } catch (error) {
      showAlert("Failed to reject staff.", "error");
    }
  };

  const showAlert = (message, severity = "success") => {
    setAlert({ show: true, message, severity });
    setTimeout(
      () => setAlert({ show: false, message: "", severity: "success" }),
      3000,
    );
  };

  const getCreatedByLabel = (staff) => {
    if (staff.created_by) {
      // The created_by is an integer id - we'll show it as reference
      return (
        <Chip
          label={`Created by staff #${staff.created_by}`}
          size="small"
          variant="outlined"
          color="info"
          sx={{ fontWeight: 500 }}
        />
      );
    }
    return (
      <Chip
        label="Self-registered"
        size="small"
        variant="outlined"
        sx={{ fontWeight: 500 }}
      />
    );
  };

  if (loading) {
    return (
      <Box
        sx={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          py: 12,
        }}
      >
        <CircularProgress size={48} sx={{ color: colors.primary }} />
      </Box>
    );
  }

  return (
    <Box
      className="page-container"
      sx={{
        minHeight: "100%",
        p: { xs: 1.5, sm: 2, md: 2.5 },
        bgcolor: "#EFF5E7",
        color: "#173F3A",
      }}
    >
      <Box sx={{ mb: 4 }}>
        <Typography
          variant="h4"
          className="page-title"
          sx={{ mb: 1, fontWeight: 900 }}
        >
          Staff Account Approvals
        </Typography>
        <Typography variant="body2" color="text.secondary">
          Review and approve pending staff registration requests.
        </Typography>
      </Box>

      {/* Summary Card */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12} sm={6} md={4}>
          <Card
            sx={{
              p: 3,
              background: "linear-gradient(135deg, #066649 0%, #07543E 100%)",
              color: "white",
              borderRadius: "18px",
              boxShadow: "0 8px 24px rgba(6,102,73,.14)",
              border: "none",
            }}
          >
            <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
              <Box
                sx={{
                  width: 60,
                  height: 60,
                  borderRadius: "12px",
                  bgcolor: "rgba(255,255,255,0.2)",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <PersonAdd sx={{ fontSize: 32 }} />
              </Box>
              <Box>
                <Typography
                  variant="body2"
                  sx={{ opacity: 0.9, fontWeight: 500 }}
                >
                  Pending Staff
                </Typography>
                <Typography variant="h4" sx={{ fontWeight: 900, mt: 0.5 }}>
                  {pendingStaff.length}
                </Typography>
              </Box>
            </Box>
          </Card>
        </Grid>
      </Grid>

      {alert.show && (
        <Alert
          severity={alert.severity}
          sx={{ mb: 3, borderRadius: "14px", animation: "fadeInUp 0.3s ease" }}
        >
          {alert.message}
        </Alert>
      )}

      {pendingStaff.length === 0 ? (
        <Paper
          sx={{
            p: 6,
            textAlign: "center",
            borderRadius: "18px",
            background:
              "linear-gradient(135deg, rgba(6,102,73,.035) 0%, rgba(39,174,128,.035) 100%)",
            border: "1px solid rgba(0,0,0,0.04)",
          }}
        >
          <Box
            sx={{
              bgcolor: "rgba(6,102,73,.10)",
              borderRadius: "18px",
              p: 2,
              display: "inline-flex",
              mb: 2,
              color: colors.primary,
            }}
          >
            <PersonAdd sx={{ fontSize: 48 }} />
          </Box>
          <Typography variant="h6" fontWeight={600} color="text.secondary">
            No pending staff account requests.
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
            New staff registrations will appear here for your approval.
          </Typography>
        </Paper>
      ) : (
        <TableContainer
          component={Paper}
          elevation={0}
          sx={{
            borderRadius: "18px",
            boxShadow: "0 18px 45px rgba(17,94,89,.07)",
            overflow: "hidden",
          }}
        >
          <Table>
            <TableHead>
              <TableRow
                sx={{
                  bgcolor: "rgba(6,102,73,.07)",
                  "& th": {
                    fontWeight: 700,
                    fontSize: "0.9rem",
                    textTransform: "uppercase",
                    letterSpacing: "0.5px",
                    color: "#173F3A",
                    borderBottom: "2px solid rgba(6,102,73,.16)",
                  },
                }}
              >
                <TableCell>User ID</TableCell>
                <TableCell>Name</TableCell>
                <TableCell>Email</TableCell>
                <TableCell>Source</TableCell>
                <TableCell>Registered</TableCell>
                <TableCell align="right">Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {pendingStaff.map((staff) => (
                <TableRow
                  key={staff.id}
                  sx={{
                    "&:hover": {
                      bgcolor: "rgba(6,102,73,.035)",
                      transition: "background-color 0.2s ease",
                    },
                    borderBottom: "1px solid rgba(0,0,0,0.06)",
                    "&:last-child td, &:last-child th": { border: 0 },
                  }}
                >
                  <TableCell>
                    <Box
                      sx={{ display: "flex", alignItems: "center", gap: 1.5 }}
                    >
                      <Avatar
                        sx={{
                          width: 40,
                          height: 40,
                          bgcolor:
                            "linear-gradient(135deg, #066649 0%, #07543E 100%)",
                          fontSize: "0.875rem",
                          fontWeight: 700,
                        }}
                      >
                        {staff.name.charAt(0).toUpperCase()}
                      </Avatar>
                      <Typography
                        variant="body2"
                        fontWeight={600}
                        sx={{ fontFamily: "monospace" }}
                      >
                        {staff.user_id || `#${staff.id}`}
                      </Typography>
                    </Box>
                  </TableCell>
                  <TableCell>
                    <Typography
                      variant="body2"
                      fontWeight={600}
                      sx={{ color: "#173F3A" }}
                    >
                      {staff.name}
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Typography variant="body2" sx={{ color: "#6B817C" }}>
                      {staff.email}
                    </Typography>
                  </TableCell>
                  <TableCell>{getCreatedByLabel(staff)}</TableCell>
                  <TableCell>
                    <Typography
                      variant="body2"
                      sx={{ color: "#6B817C", fontSize: "0.85rem" }}
                    >
                      {new Date(staff.created_at).toLocaleDateString()}
                    </Typography>
                  </TableCell>
                  <TableCell align="right">
                    <Box
                      sx={{
                        display: "flex",
                        gap: 1,
                        justifyContent: "flex-end",
                      }}
                    >
                      <Button
                        variant="contained"
                        size="small"
                        onClick={() => handleApprove(staff.id)}
                        startIcon={<CheckCircle />}
                        sx={{
                          bgcolor: "#10b981",
                          textTransform: "none",
                          fontWeight: 600,
                          fontSize: "0.85rem",
                          py: 0.75,
                          px: 2,
                          "&:hover": {
                            bgcolor: "#059669",
                            boxShadow: "0 4px 12px rgba(16,185,129,0.3)",
                          },
                        }}
                      >
                        Approve
                      </Button>
                      <Button
                        variant="outlined"
                        size="small"
                        onClick={() => handleReject(staff.id)}
                        startIcon={<Cancel />}
                        sx={{
                          color: "#ef4444",
                          borderColor: "#fca5a5",
                          textTransform: "none",
                          fontWeight: 600,
                          fontSize: "0.85rem",
                          py: 0.75,
                          px: 2,
                          "&:hover": {
                            bgcolor: "#fee2e2",
                            borderColor: "#ef4444",
                          },
                        }}
                      >
                        Reject
                      </Button>
                    </Box>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    </Box>
  );
};

export default StaffApprovals;
